pub fn debug_comments(&self) -> bool {
    self.debug_comments
}

/// Render the subtree rooted at `root` as a full HTML document, with the
/// built-in base design inlined as a `<style>` block (the default for
/// library hosts and tests).
#[must_use]
pub fn render_document(&self, opcodes: &[Opcode], strings: &[u8], root: u32) -> String {
    self.render_document_with_head(opcodes, strings, root, css::STYLE)
}

/// Render the subtree rooted at `root` as a full HTML document with the
/// built-in base design as a **separate content-hashed stylesheet link**
/// (`{css_base}/{css::builtin_css_name()}`) instead of an inline `<style>`
/// block. `css_base` is the host's reserved framework base (e.g.
/// `/_pathland`); an empty base falls back to the inline document.
///
/// Token overrides and fit-band rules stay inline (they are per-session
/// renderer state), after the stylesheet link so they win the cascade.
#[must_use]
pub fn render_document_linked(
    &self,
    opcodes: &[Opcode],
    strings: &[u8],
    root: u32,
    css_base: &str,
) -> String {
    let base = css_base.trim();
    if base.is_empty() {
        return self.render_document(opcodes, strings, root);
    }
    let head = linked_css_head(base);
    self.render_document_with_head(opcodes, strings, root, &head)
}

fn render_document_with_head(
    &self,
    opcodes: &[Opcode],
    strings: &[u8],
    root: u32,
    css_head: &str,
) -> String {
    let (nodes, tokens, window) = decode(opcodes, strings);
    let body = self.render_node(&nodes, root, None);
    // Window metadata (`META::SET_WINDOW_METADATA`) maps onto the web
    // document head. These are renderer mappings, not the protocol concept:
    // title → <title>, description → meta description, locale → lang.
    let lang = escape_html_attr(window.locale.as_deref().unwrap_or("en"));
    let title = escape(window.title.as_deref().unwrap_or("Pathland"));
    let description = window
        .description
        .as_deref()
        .map(|d| format!("<meta name=\"description\" content=\"{}\">\n", escape_html_attr(d)))
        .unwrap_or_default();
    // Token overrides render as their own `<style data-pathland-tokens>`
    // element AFTER the built-in block so their `:root` variables win the
    // cascade (same specificity, later wins) — matching the JS DOM client's
    // `style[data-pathland-tokens]` element. No overrides → no element.
    let token_rules = tokens.css();
    let token_style = if token_rules.is_empty() {
        String::new()
    } else {
        format!("<style data-pathland-tokens>{token_rules}</style>\n")
    };
    // Multi-candidate fit slots (issue #141) get their `@container` band rules
    // in a dedicated `data-pathland-fit` element (the SSR visibility contract;
    // the DOM client drops them on hydration). None in live/single-child
    // frames → no element.
    let fit_rules = fit_band_styles(&nodes);
    let fit_style = if fit_rules.is_empty() {
        String::new()
    } else {
        format!("<style data-pathland-fit>{fit_rules}</style>\n")
    };
    let scheme_attr = match tokens.scheme_override {
        Some(Scheme::Light) => " data-pathland-scheme=\"light\"",
        Some(Scheme::Dark) => " data-pathland-scheme=\"dark\"",
        None => "",
    };
    format!(
        "<!DOCTYPE html>\n<html lang=\"{lang}\"{scheme_attr}>\n<head>\n<meta charset=\"utf-8\">\n\
         <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n\
         <title>{title}</title>\n\
         {description}{css_head}{token_style}{fit_style}\n</head>\n<body>{body}</body>\n</html>\n",
    )
}

/// Render the subtree rooted at `root` as an HTML fragment (no `<html>`).
/// `SET_DESIGN_TOKEN` overrides are applied to the document head by
/// `render_document`; a fragment is assumed to be embedded in a document
/// that already defines the token variables.
#[must_use]
pub fn render_fragment(&self, opcodes: &[Opcode], strings: &[u8], root: u32) -> String {
    let (nodes, _, _) = decode(opcodes, strings);
    self.render_node(&nodes, root, None)
}

fn render_node(
    &self,
    nodes: &BTreeMap<u32, Node>,
    id: u32,
    parent_component: Option<u16>,
) -> String {
    let Some(node) = nodes.get(&id) else {
        return String::new();

    return Holder.INSTANCE;
}

/** Always available — the renderer is pure JVM code. */
public static HtmlRenderer tryInstance() {
    return Holder.INSTANCE;
}

/** True — the renderer is pure JVM code and always linkable. */
public static boolean isAvailable() {
    return true;
}

/** The generated base-design stylesheet bytes. */
public String baseCss() {
    return BaseCss.builtinCss();
}

/** The content-hashed base stylesheet asset name. */
public String baseCssName() {
    return BaseCss.builtinCssName();
}

/** Render a snapshot frame as a complete HTML document (inline base CSS). */
public String render(ProtocolFrame frame, int root) {
    return renderDocument(frame, root, BaseCss.styleElement(), false);
}

/** Render a snapshot frame as a complete HTML document linked to the hashed stylesheet. */
public String renderLinked(ProtocolFrame frame, int root, String cssBase) {
    String base = cssBase == null ? "" : cssBase.trim();
    if (base.isEmpty() || BaseCss.builtinCssName().isEmpty()) {
        return render(frame, root);
    }
    return renderDocument(frame, root, linkedCssHead(base), false);
}

/** {@link #renderLinked} with per-node debug comments. */
public String renderLinkedDebug(ProtocolFrame frame, int root, String cssBase) {
    String base = cssBase == null ? "" : cssBase.trim();
    if (base.isEmpty() || BaseCss.builtinCssName().isEmpty()) {
        return renderDebug(frame, root);
    }
    return renderDocument(frame, root, linkedCssHead(base), true);
}

/** Render a snapshot frame as an HTML fragment (no {@code <html>}). */
public String renderFragment(ProtocolFrame frame, int root) {
    Decoded decoded = decode(frame);
    return renderNode(decoded.nodes(), root, null, false);
}

/** Alias of {@link #renderFragment} for the resync snapshot path. */
public String renderFullSnapshot(ProtocolFrame frame, int root) {
    return renderFragment(frame, root);
}

/** Render a complete HTML document with per-node debug comments. */
public String renderDebug(ProtocolFrame frame, int root) {
    return renderDocument(frame, root, BaseCss.styleElement(), true);
}

/** Render an HTML fragment with per-node debug comments. */
public String renderFragmentDebug(ProtocolFrame frame, int root) {
    Decoded decoded = decode(frame);
    return renderNode(decoded.nodes(), root, null, true);
}

