public void dispatch(Iterable<Event> events) {
    try {
        ProxyHost host = proxyHost;
        if (host == null) {
            inputDispatcher.dispatch(events);
            return;
        }
        // Events whose target is in a proxy's id range belong to the origin
        // server; everything else dispatches to the app's own bindings.
        List<Event> local = new ArrayList<>();
        for (Event event : events) {
            if (!host.forward(event)) {
                local.add(event);
            }
        }
        if (!local.isEmpty()) {
            inputDispatcher.dispatch(local);
        }
    } catch (RuntimeException e) {
        LOG.warn("dropping event batch: {}", e.getMessage());
    }
}

/** Render the SSR HTML for this session's current tree (request thread). */
public String renderHtml() {
    return renderHtml(false);
}

/**
 * Render the SSR HTML. {@code serviceWorker} opts the DOM client into the
 * per-window-id service worker (issue #155) by emitting
 * {@code data-pathland-service-worker} on {@code <html>}; the client registers
 * from it (and unregisters when it is absent — the kill switch).
 */
public String renderHtml(boolean serviceWorker) {
    return renderHtml(serviceWorker, false);
}

/**
 * Render the SSR HTML. {@code serviceWorker} opts the DOM client into the
 * per-window-id service worker (issue #155) by emitting
 * {@code data-pathland-service-worker} on {@code <html>}; the client registers
 * from it (and unregisters when it is absent — the kill switch).
 *
 * <p>{@code ssrScoped} records that the request carried a real per-window id, so
 * this document was rendered with that window's persisted state — emitted as
 * {@code data-pathland-ssr-scoped} so the client can skip its initial
 * {@code META::RESYNC} (the live session shares the same scope).
 */
public String renderHtml(boolean serviceWorker, boolean ssrScoped) {
    HtmlRenderer renderer = HtmlRenderer.tryInstance();
    if (renderer == null) {
        return "<!DOCTYPE html><html><body><h1>Pathland renderer unavailable</h1>"
                + "<p>The pathland-render-html artifact is missing from the classpath.</p>"
                + "</body></html>";
    }
    ProtocolFrame frame = ssrFrame();
    // The base design is a content-hashed, immutable stylesheet under the
    // session's framework base (the same base the DOM bundle/WS use). The
    // renderer falls back to the inline document when the linked stylesheet
    // name is unavailable. Token overrides and fit-band rules remain inline.
    String html = debugHtml
            ? renderer.renderLinkedDebug(frame, rootId, base)
            : renderer.renderLinked(frame, rootId, base);
    // The reserved framework path prefix (spec): host system endpoints live
    // under `/{base}/**`. Carried as `data-pathland-base` so the DOM client
    // resolves its WebSocket and the bundle from the same base. Multi-app
    // hosts give each mounted app its own base (e.g. `/app2/_pathland`).
    // The bundle name is content-hashed (see PathlandAssets) so a new build
    // busts the immutable asset cache via a fresh URL.
    String htmlAttrs = " data-pathland-base=\"" + base + "\""
            + (serviceWorker ? " data-pathland-service-worker=\"true\"" : "")
            + (ssrScoped ? " data-pathland-ssr-scoped=\"true\"" : "");
    String integrity = PathlandAssets.bundleIntegrity();
    String integrityAttr = integrity.isEmpty() ? "" : " integrity=\"" + integrity + "\"";
    return injectHtmlAttributes(html, htmlAttrs)
            .replace("</body>", "<script src=\"" + base + "/" + PathlandAssets.bundleName()
                    + "\"" + integrityAttr + " defer></script></body>");
}

/**
 * Add host attributes to the renderer's opening {@code <html …>} tag. The
 * renderer may already carry {@code lang} (window metadata), so this must not
 * depend on an exact {@code <html>} string.
 */
private static String injectHtmlAttributes(String html, String attrs) {
    int start = html.indexOf("<html");
    if (start < 0) {
        return html;
    }
    int end = html.indexOf('>', start);

    /** The renderer-owned icon glyphs at the global base — `/_pathland/icons/<name>.svg`.
     *  These have no static file: every host serves them from the shared Rust renderer
     *  (`pathland_html_icon_svg` over the C ABI, the same `icons` source SSR inlines). */
    @GET
    @Path("/_pathland/icons/{name}.svg")
    @Produces("image/svg+xml")
    public Response icon(@PathParam("name") String name) {
        return iconResponse(name);
    }

    /** The renderer-owned content-hashed base stylesheet at the global base. */
    @GET
    @Path("/_pathland/{name}.css")
    @Produces("text/css")
    public Response baseCss(@PathParam("name") String name) {
        Response css = baseCssResponse(name + ".css");
        return css != null ? css : Response.status(Response.Status.NOT_FOUND).build();
    }

    /** Serve a mounted app's framework file (its {@code data-pathland-base} bundle) from the shared classpath mount. */
    private Response frameworkFile(String file) throws IOException {
        // Quarkus web static lives in META-INF/resources (classpath resource root), so the
        // shared `/_pathland/**` mount resolves as /META-INF/resources/_pathland/<file>.
        try (InputStream in = getClass().getResourceAsStream("/META-INF/resources/_pathland/" + file)) {
            if (in != null) {
                return Response.ok(in.readAllBytes()).type(mediaTypeOf(file)).build();
            }
        }
        // No static file (a host override would be served above) — the base design
        // is renderer-owned and content-hashed.
        Response css = baseCssResponse(file);
        if (css != null) {
            return css;
        }
        // Renderer-owned icon glyphs come from the shared Rust renderer; a
        // single-segment name is required (the DOM client requests exactly
        // {base}/icons/<encodeURIComponent>).
        if (file.startsWith("icons/") && file.endsWith(".svg")
                && file.substring("icons/".length(), file.length() - ".svg".length()).indexOf('/') < 0) {
            return iconResponse(file.substring("icons/".length(), file.length() - ".svg".length()));
        }
        return Response.status(Response.Status.NOT_FOUND).build();
    }

    /** The renderer-owned content-hashed base stylesheet, or {@code null}. */
    private Response baseCssResponse(String file) {
        var renderer = dev.pathland.render.html.HtmlRenderer.tryInstance();
        if (renderer == null) {
            return null;
        }
        String name = renderer.baseCssName();
        if (name.isEmpty() || !name.equals(file)) {
            return null;
        }
        String css = renderer.baseCss();
        if (css.isEmpty()) {
            return null;
        }
        return Response.ok(css.getBytes(java.nio.charset.StandardCharsets.UTF_8))
                .type("text/css")
                .header("Cache-Control", IMMUTABLE)
                .build();
    }

    /** The renderer-owned `/_pathland/icons/<name>.svg` from the shared Rust library. */
    private Response iconResponse(String name) {
        var renderer = dev.pathland.render.html.HtmlRenderer.tryInstance();
        String svg = renderer == null ? null : renderer.iconSvg(name);
        if (svg == null) {
            return Response.status(Response.Status.NOT_FOUND).build();
        }
        return Response.ok(svg.getBytes(java.nio.charset.StandardCharsets.UTF_8))
                .type(new MediaType("image", "svg+xml"))
                .header("Cache-Control", "public, max-age=2592000, immutable")
                .build();
    }

    private static MediaType mediaTypeOf(String file) {
        if (file.endsWith(".js")) {
            return new MediaType("application", "javascript");
        }
        if (file.endsWith(".svg")) {
            return new MediaType("image", "svg+xml");
        }
        if (file.endsWith(".mp3")) {
            return new MediaType("audio", "mpeg");
        }
        if (file.endsWith(".mp4")) {
            return new MediaType("video", "mp4");
        }
        return MediaType.APPLICATION_OCTET_STREAM_TYPE;
    }
}

