/// caller (release with [`pathland_html_free`]).
#[no_mangle]
pub extern "C" fn pathland_html_base_css_name() -> *const c_char {
    match CString::new(css::builtin_css_name()) {
        Ok(cs) => cs.into_raw(),
        Err(_) => std::ptr::null(),
